SELECT 
FROM order_header
WHERE user_id = #{userId} AND is_deleted = 0

    AND status = #{status}

ORDER BY create_time DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(1)
FROM order_header
WHERE user_id = #{userId}
  AND service_item_id = #{serviceItemId}
  AND service_date = #{serviceDate}
  AND service_time_slot = #{serviceTimeSlot}
  AND status IN (0, 1)
  AND is_deleted = 0

mapper.update:
UPDATE order_header
SET status = #{toStatus},
    version = version + 1,
    cancel_reason = #{cancelReason},
    update_time = NOW()
WHERE id = #{id}
  AND status = #{fromStatus}
  AND version = #{version}
  AND is_deleted = 0
